<?php

namespace models\scolarite;

use core\Model;
use Database;
use models\acteurs\Enseignant;

/**
 * Modèle associant un enseignant comme membre du jury d'une évaluation (table TD_JURY).
 *
 * @author  AutoGenerated / POO Refactor
 * @version 1.0
 */
class Jury extends Model
{
    public string $PER_ID;
    public string $EVA_ID;

    /**
     * Instancie et hydrate le modèle à partir d'un tableau associatif.
     *
     * @param array<string, mixed> $data
     * @return static
     */
    public static function fromArray(array $data): static
    {
        return (new static())->hydrate($data);
    }

    /**
     * Recherche un enregistrement par sa clé composite (PER_ID, EVA_ID).
     *
     * @param string $per_id
     * @param string $eva_id
     * @return static|null
     */
    public static function find(string $per_id, string $eva_id): ?static
    {
        $stmt = Database::getInstance()->prepare('SELECT * FROM TD_JURY WHERE PER_ID = ? AND EVA_ID = ? LIMIT 1');
        $stmt->execute([$per_id, $eva_id]);
        $row = $stmt->fetch();

        return $row ? (new static())->hydrate($row) : null;
    }

    /**
     * Récupère tous les enregistrements de la table.
     *
     * @return static[]
     */
    public static function findAll(): array
    {
        $stmt = Database::getInstance()->query('SELECT * FROM TD_JURY');
        $rows = $stmt->fetchAll();

        return array_map(fn($row) => (new static())->hydrate($row), $rows);
    }

    /**
     * Récupère les instances Jury associées à un objet Enseignant.
     *
     * @param Enseignant $source
     * @return static[]
     */
    public static function getFromEnseignant(Enseignant $source): array
    {
        $stmt = Database::getInstance()->prepare('SELECT * FROM TD_JURY WHERE PER_ID = ?');
        $stmt->execute([$source->PER_ID]);
        $rows = $stmt->fetchAll();

        return array_map(fn($row) => (new static())->hydrate($row), $rows);
    }

    /**
     * Navigue vers l'objet Enseignant parent lié à cet enregistrement.
     *
     * @return Enseignant|null
     */
    public function getEnseignant(): ?Enseignant
    {
        if (!isset($this->PER_ID)) {
            return null;
        }
        return Enseignant::findById($this->PER_ID);
    }

    /**
     * Récupère les instances Jury associées à un objet Evaluation.
     *
     * @param Evaluation $source
